import { test } from 'node:test';
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { interpretBleServiceData, MAX_BTHOME_OBJECTS } from '../packages/core/ble-advertisements.ts';
const decode = (wire: string) => {
  const result = interpretBleServiceData('fcd2', wire);
  assert.ok('format' in result && result.format === 'BTHome-v2');
  return result;
};
// Independently hand-calculated synthetic vectors, not generated by the decoder
// or the upstream parser. Literal bytes include asymmetric little-endian values.
const goldens = [
  ['063930', 'mass', 'kg', 12345, 100, 123.45, false],
  ['07d204', 'mass', 'lb', 1234, 100, 12.34, false],
  ['082efb', 'dew-point', '°C', -1234, 100, -12.34, true],
  ['09fe', 'count', null, 254, 1, 254, false],
  ['0a563412', 'energy', 'kWh', 1193046, 1000, 1193.046, false],
  ['0b563412', 'power', 'W', 1193046, 100, 11930.46, false],
  ['0d3412', 'pm2.5', 'µg/m³', 4660, 1, 4660, false],
  ['0e7856', 'pm10', 'µg/m³', 22136, 1, 22136, false],
  ['143930', 'moisture', '%', 12345, 100, 123.45, false],
  ['2f64', 'moisture', '%', 100, 1, 100, false],
  ['3d3412', 'count', null, 4660, 1, 4660, false],
  ['3eefcdab89', 'count', null, 2309737967, 1, 2309737967, false],
  ['3f7bfc', 'rotation', '°', -901, 10, -90.1, true],
  ['403412', 'distance', 'mm', 4660, 1, 4660, false],
  ['413412', 'distance', 'm', 4660, 10, 466, false],
  ['42563412', 'duration', 's', 1193046, 1000, 1193.046, false],
  ['43d204', 'current', 'A', 1234, 1000, 1.234, false],
  ['44d204', 'speed', 'm/s', 1234, 100, 12.34, false],
  ['467b', 'uv-index', null, 123, 10, 12.3, false],
  ['473412', 'volume', 'L', 4660, 10, 466, false],
  ['483412', 'volume', 'mL', 4660, 1, 4660, false],
  ['49d204', 'volume-flow-rate', 'm³/h', 1234, 1000, 1.234, false],
  ['4defcdab89', 'energy', 'kWh', 2309737967, 1000, 2309737.967, false],
  ['5d2efb', 'current', 'A', -1234, 1000, -1.234, true],
] as const;

test('24 additional scalar IDs retain independent golden values, units and exact rational evidence', () => {
  for (const [wire, property, unit, rawInteger, scaleDivisor, value] of goldens) {
    const result = decode('40' + wire);
    assert.equal(result.parseStatus, 'complete', wire);
    assert.equal(result.status, 'format-match');
    assert.deepEqual(result.objects, [{ offset: 1, objectId: parseInt(wire.slice(0,2),16), occurrence: 1,
      property, unit, rawHex: wire, rawInteger, scaleDivisor, value }]);
    assert.equal(result.authenticated, false); assert.equal(result.sensorTruthVerified, false);
  }
});
test('new scalar types preserve zero, all-bits-set and high-bit extrema without clamps', () => {
  for (const [wire, , , , divisor, , signed] of goldens) {
    const id = wire.slice(0,2), width = wire.length / 2 - 1;
    const cases: [string, number][] = [
      ['00'.repeat(width), 0],
      ['ff'.repeat(width), signed ? -1 : 2 ** (width * 8) - 1],
      ['00'.repeat(width - 1) + '80', signed ? -(2 ** (width * 8 - 1)) : 2 ** (width * 8 - 1)],
      ['ff'.repeat(width - 1) + '7f', 2 ** (width * 8 - 1) - 1],
    ];
    for (const [bytes, raw] of cases) {
      const result = decode('40' + id + bytes);
      assert.equal(result.parseStatus, 'complete');
      assert.equal(result.objects[0]!.rawInteger, raw, id + bytes);
      assert.equal(result.objects[0]!.value, raw / divisor);
    }
  }
});
test('every proper prefix of each new field stops after a valid original field without consuming bytes', () => {
  for (const [wire] of goldens) for (let end = 2; end < wire.length; end += 2) {
    const tail = wire.slice(0,end), result = decode('400101' + tail);
    assert.equal(result.status, 'invalid'); assert.equal(result.parseStatus, 'malformed');
    assert.equal(result.objects.length, 1); assert.equal(result.unparsedHex, tail);
    assert.deepEqual(result.issues, [{ offset: 3, code: 'truncated-object' }]);
  }
});
test('mixed original/new stream preserves ordering, repeated IDs, offsets and complete byte reconstruction', () => {
  const fields = ['0101', '063930', '063930', '07d204', '082efb', '0c020c', '3eefcdab89', '3eefcdab89', '5bea0234ea', '5d2efb'];
  const result = decode('44' + fields.join(''));
  assert.equal(result.parseStatus, 'complete'); assert.equal(result.triggerBased, true);
  assert.deepEqual(result.objects.map(o => o.offset), [1,3,6,9,12,15,18,23,28,33]);
  assert.deepEqual(result.objects.map(o => o.occurrence), [1,1,2,1,1,1,1,2,1,1]);
  assert.deepEqual(result.objects.map(o => o.rawHex), fields);
  assert.equal('44' + result.objects.map(o => o.rawHex).join('') + result.unparsedHex, result.payloadHex);
  const descending = decode('40073930063930');
  assert.deepEqual(descending.issues, [{ offset: 4, code: 'object-order' }]);
  assert.equal(descending.unparsedHex, '063930'); assert.equal(descending.objects.length, 1);
});
test('all new scalar fields compose into an ordered stream and survive encrypted-header gating', () => {
  const wire = goldens.map(g => g[0]).join('');
  const result = decode('40' + wire);
  assert.equal(result.parseStatus, 'complete'); assert.equal(result.objects.length, 24);
  assert.deepEqual(result.objects.map(o => o.value), goldens.map(g => g[5]));
  for (const header of ['41','45','ff']) {
    const opaque = decode(header + wire);
    assert.equal(opaque.parseStatus, 'opaque'); assert.deepEqual(opaque.objects, []);
    assert.equal(opaque.unparsedHex, header + wire);
  }
});
test('excluded objects stop without guessing across numeric-looking tails', () => {
  for (const id of ['0f','13','3a','3b','3c','50','53','54','56','58','60','f0','ff']) {
    const result = decode('40063930' + id + '0639305d2efb');
    assert.equal(result.status, 'opaque'); assert.equal(result.parseStatus, 'unsupported-object');
    assert.equal(result.objects.length, 1); assert.equal(result.unparsedHex, id + '0639305d2efb');
    assert.deepEqual(result.issues, [{ offset: 4, code: 'unknown-object' }]);
  }
});
test('wide unsigned values obey the unchanged 128-object cap', () => {
  const field = '3effffffff';
  assert.equal(decode('40' + field.repeat(MAX_BTHOME_OBJECTS)).parseStatus, 'complete');
  const result = decode('40' + field.repeat(MAX_BTHOME_OBJECTS + 1));
  assert.equal(result.objects.length, 128); assert.equal(result.parseStatus, 'limit-exceeded');
  assert.equal(result.unparsedHex, field);
  assert.deepEqual(result.issues, [{ offset: 641, code: 'object-limit' }]);
});
test('retained MIT constants and license remain exactly the pinned local source bytes', () => {
  for (const [file, sha256, blob] of [
    ['const.py.reference', '981cf0ad0dd7a7b515ff87e23b2e964666ae30dc8ee1ad3ff41bd3f6869ce026', '5882a869e6f15038189feda5d9989bdf35b58c81'],
    ['LICENSE.bthome-ble', '1dfcd486d66431c1aedbca5a43024cc1ef64f098d5d10fdc7bdf3f65873436f8', '1e41c3a4cc71717d8e8360072326ac8196bcc406'],
  ]) {
    const bytes = readFileSync(new URL('../research/bthome-reference/' + file, import.meta.url));
    assert.equal(createHash('sha256').update(bytes).digest('hex'), sha256);
    assert.equal(createHash('sha1').update(`blob ${bytes.length}\0`).update(bytes).digest('hex'), blob);
  }
});
